// n8n 2.43.5 SAFE get helper
function getJsons(name){
  try{
    const n = $(name);
    if(n && Array.isArray(n.all)) return n.all.map(i=>i.json||i);
  }catch(e){}
  try{
    const a = $items(name, 0, 0);
    if(Array.isArray(a)) return a.map(i=>i.json||i);
  }catch(e){}
  try{
    const a2 = $items(name);
    if(Array.isArray(a2)) return a2.map(i=>i.json||i);
  }catch(e){}
  return [];
}

const digestRaw = getJsons('Supabase - Get Digest');
const digest = digestRaw[0] || {};

const top5 = getJsons('Supabase - Top 5 Action');
const sla = getJsons('Supabase - SLA Today');

const today = new Date().toLocaleDateString('en-AE', { timeZone: 'Asia/Dubai' });

const leadsToday = digest.leads_today ?? digest.total_today ?? 1;
const hotToday = digest.hot_today ?? digest.hot_count ?? top5.filter(t=>t.band==='Hot').length;
const warmToday = digest.warm_today ?? 0;
const coldToday = digest.cold_today ?? 0;
const breachesToday = digest.sla_breaches_today ?? digest.sla_count ?? sla.length;

let top5Rows = top5.length ? top5.map(t=>`
<tr>
<td style="padding:8px;border:1px solid #ddd">${t.name}</td>
<td style="padding:8px;border:1px solid #ddd">${t.phone}</td>
<td style="padding:8px;border:1px solid #ddd">${t.location || '-'}</td>
<td style="padding:8px;border:1px solid #ddd"><b>${t.band} ${t.score}</b></td>
<td style="padding:8px;border:1px solid #ddd">${t.reason || t.intent || ''}</td>
</tr>`).join('') : `<tr><td colspan="5" style="padding:12px;text-align:center;color:#888">No Hot leads today — queue cleared ✅</td></tr>`;

let slaRows = sla.length ? sla.map(s=>`
<tr style="background:#ffecec">
<td style="padding:8px;border:1px solid #ddd">${s.name}</td>
<td style="padding:8px;border:1px solid #ddd">${s.phone}</td>
<td style="padding:8px;border:1px solid #ddd">${s.minutes_overdue ?? '-'} min</td>
<td style="padding:8px;border:1px solid #ddd">${s.follow_up_due_at || s.sent_at || ''}</td>
</tr>`).join('') : `<tr><td colspan="4" style="padding:12px;text-align:center;color:green">✅ No SLA breach today</td></tr>`;

const html = `
<h2 style="font-family:Arial">📊 Dubai Ops Digest - ${today}</h2>
<table style="border-collapse:collapse;width:100%;font-family:Arial;margin-bottom:16px">
<tr style="background:#f3f4f6"><td style="padding:8px;border:1px solid #ddd">Leads Today</td><td style="padding:8px;border:1px solid #ddd"><b>${leadsToday}</b></td></tr>
<tr><td style="padding:8px;border:1px solid #ddd">Hot 🔥</td><td style="padding:8px;border:1px solid #ddd"><b>${hotToday}</b></td></tr>
<tr style="background:#f3f4f6"><td style="padding:8px;border:1px solid #ddd">Warm</td><td style="padding:8px;border:1px solid #ddd">${warmToday}</td></tr>
<tr><td style="padding:8px;border:1px solid #ddd">Cold</td><td style="padding:8px;border:1px solid #ddd">${coldToday}</td></tr>
<tr style="background:#ffeaea"><td style="padding:8px;border:1px solid #ddd">SLA Breaches Today</td><td style="padding:8px;border:1px solid #ddd"><b>${breachesToday}</b></td></tr>
</table>

<h3>🔥 Top 5 Action Leads (Call NOW)</h3>
<table style="border-collapse:collapse;width:100%;font-family:Arial">
<tr style="background:#111;color:#fff"><th style="padding:8px">Name</th><th>Phone</th><th>Location</th><th>Score</th><th>Reason</th></tr>
${top5Rows}
</table>

<h3 style="margin-top:20px">🚨 SLA Breaches Today</h3>
<table style="border-collapse:collapse;width:100%;font-family:Arial">
<tr style="background:#111;color:#fff"><th style="padding:8px">Name</th><th>Phone</th><th>Overdue</th><th>Due At</th></tr>
${slaRows}
</table>
<p style="font-family:Arial;color:#666;font-size:12px;margin-top:20px">FREE stack: n8n 2.43.5 + Supabase RPC + Gmail + Gemini 3.5-flash-lite • ${today} Asia/Dubai</p>
`;

return [{ json: { html, top5_count: top5.length, sla_count: sla.length, today } }];
